-- 0015_alcoa_suprema_portao_moveleira.sql
-- Decisao explicita do responsavel tecnico (2026-08-16): usar o indice de perfis do
-- Catalogo Alcoa (fonte 11, ja carregada em 0014) como base para (a) resolver o conflito
-- de peso da linha Suprema e (b) tentar confirmar o fabricante de Linha Portao e Linha
-- Moveleira, que seguiam NECESSITA_CONFERENCIA.
--
-- IMPORTANTE sobre forca de evidencia (nao e a mesma para as 3 linhas):
--  * Suprema: 36 de 41 codigos (88%) batem, todos na faixa de pagina 157-202
--    (secao 'Linha Suprema' do indice Alcoa), diferenca de peso pequena e sistematica
--    (+1% a +11%, quase sempre Alcoa > TEC-SUP) -- evidencia forte de que e o mesmo perfil.
--  * Linha Moveleira: 6 de 12 codigos verificados (50%) batem, mas em
--    paginas espalhadas (54, 69, 174-188) em vez de uma secao unica -- consistente com pecas
--    genericas (baguete, remate) reaproveitadas em varias linhas do catalogo, evidencia mais
--    fraca que a de Suprema/Modulo Pratico.
--  * Linha Portao: 2 de 8 codigos (25%) batem -- no limite minimo do
--    criterio (n>=2, ratio>=0.25), e um dos dois (PU-639) aparece com pagina divergente em
--    outro ponto do proprio indice Alcoa (conflito interno da fonte). Confirmacao mais fraca
--    das tres; recomenda-se conferencia com o fabricante antes de tratar como definitiva.

INSERT INTO source_references (technical_source_id, section_title, excerpt, extracted_by) VALUES
