UPDATE profiles SET weight_kg_per_m=0.624, status_code='CATALOGADO', origin_type='ENCONTRADO_DOCUMENTO', source_reference_id=@ref_portao, description=CONCAT(COALESCE(description,''), ' | Peso: Catalogo Alcoa, Indice de Perfis, pag. 72 (evidencia fraca, ver nota da linha).') WHERE product_line_id=8 AND code='LB-050';

-- === LINHA MOVELEIRA (product_line_id=9): tinha atribuicao fraca anterior (so mencao na
-- === contracapa do catalogo Ecoline 2.5, sem codigo). Evidencia de codigo contra o indice
-- === Alcoa (50%, paginas espalhadas) e mais forte que a mencao anterior, entao substitui.
UPDATE product_lines SET
manufacturer_id = 2,
status_code = 'CATALOGADO',
description = CONCAT(description, ' | Fabricante reatribuido a Alcoa em 2026-08-16 por instrucao explicita do usuario: 6 de 12 codigos verificados (50%) batem contra o indice de perfis Alcoa, superando a evidencia anterior (mera mencao textual na contracapa do catalogo Ecoline 2.5, sem codigo). Paginas espalhadas (nao uma secao unica), entao a confianca no fabricante e maior que no peso individual de cada perfil. Ver source_references.id=', @ref_moveleira, '.'),
source_reference_id = @ref_moveleira
WHERE id = 9;

UPDATE profiles SET manufacturer_id = 2 WHERE product_line_id = 9;

